N = int(input())

matrix = []
for _ in range(N):
    row = list(map(int, input().strip().split()))
    matrix.append(row)

for i in range(N):
  ans = []
  for j in range(N):
    if matrix[i][j] == 1:
      ans.append(j + 1)
  print(*ans)
